style.css:
/* Set a background image for Discord */
body {
    background-image: url(https://i.pinimg.com/736x/30/dc/88/30dc880e6c790d3048667cbc3cf89f60.jpg) !important; /* Replace with the URL of your image */
    background-size: cover !important; /* Ensures the image covers the entire background */
    background-repeat: no-repeat !important; /* Prevents the image from repeating */
    background-attachment: fixed !important; /* Keeps the image fixed while scrolling */
    color: #6b1616 !important; /* Deep red text to match the goth aesthetic */
}
